using Microsoft.EntityFrameworkCore;

namespace TechHRMS.Api;

/// <summary>Additive versioned operational schema. Never drops tables, employees, accounts or passwords.</summary>
public static class OperationsSchema
{
    public static async Task InitializeAsync(IServiceProvider services, IWebHostEnvironment env, IConfiguration config)
    {
        using var scope = services.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<HrDb>();
        var pg = db.Database.IsNpgsql();
        if (!pg && !db.Database.IsSqlite()) throw new InvalidOperationException("Unsupported database provider.");
        await using var tx = await db.Database.BeginTransactionAsync();
        if (pg) await db.Database.ExecuteSqlRawAsync("SELECT pg_advisory_xact_lock(47424002)");
        var id = pg ? "integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY" : "INTEGER PRIMARY KEY AUTOINCREMENT";
        var date = pg ? "date" : "TEXT";
        var instant = pg ? "timestamp with time zone" : "TEXT";
        var money = pg ? "numeric" : "TEXT";
        var flag = pg ? "boolean" : "INTEGER";
        var revision = pg ? "bigint" : "INTEGER";
        var statements = new[] {
            $"""CREATE TABLE IF NOT EXISTS "OperationsSchemaVersions" ("Version" integer PRIMARY KEY, "AppliedAtUtc" {instant} NOT NULL)""",
            $"""CREATE TABLE IF NOT EXISTS "LeaveEntitlements" ("Id" {id}, "EmployeeId" integer NOT NULL REFERENCES "Employees"("Id") ON DELETE RESTRICT, "Year" integer NOT NULL, "Entitlement" integer NOT NULL)""",
            $"""CREATE TABLE IF NOT EXISTS "WorkRequestDetails" ("Id" {id}, "RequestId" integer NOT NULL REFERENCES "WorkRequests"("Id") ON DELETE CASCADE, "Hours" {money} NULL)""",
            $"""CREATE TABLE IF NOT EXISTS "AppNotifications" ("Id" {id}, "EmployeeId" integer NOT NULL REFERENCES "Employees"("Id") ON DELETE RESTRICT, "Title" TEXT NOT NULL, "Message" TEXT NOT NULL, "Link" TEXT NOT NULL, "IsRead" {flag} NOT NULL, "CreatedAtUtc" {instant} NOT NULL)""",
            $"""CREATE TABLE IF NOT EXISTS "ProjectTimesheets" ("Id" {id}, "EmployeeId" integer NOT NULL REFERENCES "Employees"("Id") ON DELETE RESTRICT, "ProjectId" integer NOT NULL REFERENCES "Projects"("Id") ON DELETE RESTRICT, "WorkDate" {date} NOT NULL, "Hours" {money} NOT NULL, "Billable" {flag} NOT NULL, "Note" TEXT NOT NULL, "Status" TEXT NOT NULL, "ReviewNote" TEXT NOT NULL, "ReviewedById" integer NULL, "CreatedAtUtc" {instant} NOT NULL)""",
            $"""CREATE TABLE IF NOT EXISTS "PayrollPeriods" ("Id" {id}, "Month" TEXT NOT NULL, "Title" TEXT NOT NULL, "Status" TEXT NOT NULL, "CreatedById" integer NOT NULL, "ApprovedById" integer NULL, "CreatedAtUtc" {instant} NOT NULL, "PublishedAtUtc" {instant} NULL)""",
            $"""CREATE TABLE IF NOT EXISTS "PayrollItems" ("Id" {id}, "PeriodId" integer NOT NULL REFERENCES "PayrollPeriods"("Id") ON DELETE RESTRICT, "EmployeeId" integer NOT NULL REFERENCES "Employees"("Id") ON DELETE RESTRICT, "EmployeeName" TEXT NOT NULL, "BaseSalary" {money} NOT NULL, "Allowances" {money} NOT NULL, "Bonus" {money} NOT NULL, "Deductions" {money} NOT NULL, "Note" TEXT NOT NULL)""",
            $"""CREATE TABLE IF NOT EXISTS "OffboardingCases" ("Id" {id}, "EmployeeId" integer NOT NULL REFERENCES "Employees"("Id") ON DELETE RESTRICT, "LastWorkingDate" {date} NOT NULL, "Reason" TEXT NOT NULL, "Status" TEXT NOT NULL, "CompletedAtUtc" {instant} NULL)""",
            $"""CREATE TABLE IF NOT EXISTS "OffboardingTasks" ("Id" {id}, "CaseId" integer NOT NULL REFERENCES "OffboardingCases"("Id") ON DELETE CASCADE, "Title" TEXT NOT NULL, "Done" {flag} NOT NULL)""",
            $"""CREATE TABLE IF NOT EXISTS "CandidateHires" ("Id" {id}, "CandidateId" integer NOT NULL REFERENCES "Candidates"("Id") ON DELETE RESTRICT, "EmployeeId" integer NOT NULL REFERENCES "Employees"("Id") ON DELETE RESTRICT, "HiredAtUtc" {instant} NOT NULL)""",
            $"""CREATE TABLE IF NOT EXISTS "OperationLocks" ("Id" integer PRIMARY KEY, "Revision" {revision} NOT NULL)""",
            "CREATE UNIQUE INDEX IF NOT EXISTS \"IX_LeaveEntitlements_EmployeeId_Year\" ON \"LeaveEntitlements\" (\"EmployeeId\", \"Year\")",
            "CREATE UNIQUE INDEX IF NOT EXISTS \"IX_WorkRequestDetails_RequestId\" ON \"WorkRequestDetails\" (\"RequestId\")",
            "CREATE INDEX IF NOT EXISTS \"IX_AppNotifications_EmployeeId_IsRead_CreatedAtUtc\" ON \"AppNotifications\" (\"EmployeeId\", \"IsRead\", \"CreatedAtUtc\")",
            "CREATE UNIQUE INDEX IF NOT EXISTS \"IX_ProjectTimesheets_EmployeeId_ProjectId_WorkDate\" ON \"ProjectTimesheets\" (\"EmployeeId\", \"ProjectId\", \"WorkDate\")",
            "CREATE UNIQUE INDEX IF NOT EXISTS \"IX_PayrollPeriods_Month\" ON \"PayrollPeriods\" (\"Month\")",
            "CREATE UNIQUE INDEX IF NOT EXISTS \"IX_PayrollItems_PeriodId_EmployeeId\" ON \"PayrollItems\" (\"PeriodId\", \"EmployeeId\")",
            "CREATE UNIQUE INDEX IF NOT EXISTS \"IX_OffboardingCases_EmployeeId\" ON \"OffboardingCases\" (\"EmployeeId\")",
            "CREATE UNIQUE INDEX IF NOT EXISTS \"IX_CandidateHires_CandidateId\" ON \"CandidateHires\" (\"CandidateId\")",
            "CREATE UNIQUE INDEX IF NOT EXISTS \"IX_CandidateHires_EmployeeId\" ON \"CandidateHires\" (\"EmployeeId\")",
            "INSERT INTO \"OperationLocks\" (\"Id\", \"Revision\") VALUES (1,0) ON CONFLICT (\"Id\") DO NOTHING"
        };
        foreach (var statement in statements) await db.Database.ExecuteSqlRawAsync(statement);
        await db.Database.ExecuteSqlInterpolatedAsync($"INSERT INTO \"OperationsSchemaVersions\" (\"Version\", \"AppliedAtUtc\") VALUES (1,{DateTime.UtcNow}) ON CONFLICT (\"Version\") DO NOTHING");
        await tx.CommitAsync();
    }
}
